from pydantic import BaseModel, Field

class Document(BaseModel):
    """Extracted information from a single judgment document for classification."""
    title: str = Field(description="The title of the judgment document (e.g., '《判决文书1》')")
    classification_keywords: list[str] = Field(
        description="Keywords found in the document that indicate its legal nature and procedural type (e.g., '执行异议', '国家赔偿', '管辖权异议', '刑事二审', '行政赔偿'). These are used to map the document to one of the 6 task categories."
    )
    document_type: str = Field(description="The type of legal document (e.g., 裁定书, 判决书, 决定书)")

class Parse(BaseModel):
    documents: list[Document]
